import type {MedusaRequest,MedusaResponse} from '@medusajs/framework/http'
import {ContainerRegistrationKeys} from '@medusajs/framework/utils'
const actor=(r:MedusaRequest)=>(r as any).auth_context?.actor_id||(r as any).auth_context?.auth_identity_id
async function seller(req:MedusaRequest,a:string){const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;try{const {data}=await q.graph({entity:'seller_member',fields:['seller.id','seller.name','seller.email'],filters:{member_id:a},pagination:{take:1}});return data?.[0]?.seller||null}catch{return null}}
export async function GET(req:MedusaRequest,res:MedusaResponse){const a=actor(req);if(!a)return res.status(401).json({message:'Unauthorized'});const s=await seller(req,a),sp=req.scope.resolve('spike') as any;if(!s)return res.status(404).json({message:'Seller not found'});const rows=await sp.listSpikeSettings({key:`seller_profile:${s.id}`},{take:1});res.json({seller:s,profile:rows[0]?.value||{}})}
export async function POST(req:MedusaRequest,res:MedusaResponse){const a=actor(req);if(!a)return res.status(401).json({message:'Unauthorized'});const s=await seller(req,a),sp=req.scope.resolve('spike') as any,b=(req.body||{}) as any;if(!s)return res.status(404).json({message:'Seller not found'});if(b.latitude==null||b.longitude==null)return res.status(422).json({message:'حدد موقع المتجر على الخريطة',field:'location'});const value={phone:String(b.phone||''),address:String(b.address||''),city:String(b.city||''),governorate:String(b.governorate||''),latitude:Number(b.latitude),longitude:Number(b.longitude),google_maps_url:String(b.google_maps_url||'')};const key=`seller_profile:${s.id}`,r=await sp.listSpikeSettings({key},{take:1});r.length?await sp.updateSpikeSettings({id:r[0].id,value}):await sp.createSpikeSettings({key,value});res.json({profile:value})}
